'use strict';
class StreetFight {
  constructor(){
    this.canvas=document.getElementById('fight-canvas');this.ctx=this.canvas.getContext('2d');this.ctx.imageSmoothingEnabled=false;
    this.keys=new Set();this.pressed=new Set();this.running=false;this.ready=false;this.last=0;this.round=1;this.pWins=0;this.cWins=0;this.time=99;this.countdown=0;this.projectiles=[];this.frameCache=new Map();this.endTimer=0;
    this.assets={};this.assetPaths={bg:'assets/ocean-drive.png',pMove:'assets/birrow-move.png',pAttack:'assets/birrow-attacks.png',pReact:'assets/birrow-reactions.png',cpu:'assets/halfred-sprites.png'};
    addEventListener('keydown',e=>{if(!this.running)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Shift','j','k','u','i','l','o','J','K','U','I','L','O'].includes(e.key)){e.preventDefault();this.keys.add(e.key.toLowerCase());this.pressed.add(e.key.toLowerCase());}});
    addEventListener('keyup',e=>this.keys.delete(e.key.toLowerCase()));
  }
  async load(){if(this.ready)return;await Promise.all(Object.entries(this.assetPaths).map(([k,src])=>new Promise(resolve=>{const im=new Image();im.onload=()=>{this.assets[k]=im;resolve()};im.onerror=resolve;im.src=src})));this.ready=true;}
  makeFighter(side){return side==='p'?{side,x:300,y:610,vx:0,vy:0,dir:1,life:1000,power:0,state:'idle',row:0,frame:0,clock:0,attack:null,hitstun:0,ground:true}:{side,x:980,y:610,vx:0,vy:0,dir:-1,life:1000,power:0,state:'idle',row:0,frame:0,clock:0,attack:null,hitstun:0,ground:true,ai:0};}
  async start(){await this.load();this.running=true;this.round=1;this.pWins=0;this.cWins=0;this.resetRound();this.last=performance.now();requestAnimationFrame(t=>this.loop(t));}
  stop(){this.running=false;this.keys.clear();this.pressed.clear();}
  resetRound(){this.player=this.makeFighter('p');this.cpu=this.makeFighter('c');this.projectiles.length=0;this.time=99;this.countdown=2.2;this.endTimer=0;this.updateHud();this.callout('ROUND '+this.round);setTimeout(()=>this.running&&this.callout('FIGHT!'),900);}
  callout(text){const el=document.getElementById('fight-message');el.textContent=text;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');}
  attack(f,type){if(f.attack||f.hitstun||this.countdown>0||this.endTimer)return;const p=f.side==='p';const cfg={jab:{duration:.31,active:[.09,.16],damage:42,reach:82,row:0},kick:{duration:.48,active:[.18,.28],damage:65,reach:116,row:1},heavy:{duration:.58,active:[.24,.34],damage:82,reach:96,row:0},sweep:{duration:.62,active:[.24,.38],damage:76,reach:126,row:3,knock:true},neon:{duration:.72,active:[.3,.4],damage:88,reach:0,row:2,projectile:true,cost:35},spin:{duration:.65,active:[.25,.4],damage:105,reach:135,row:3,knock:true,cost:50},charge:{duration:.68,active:[.25,.48],damage:98,reach:150,row:2,cost:0},pulse:{duration:.75,active:[.32,.52],damage:86,reach:150,row:3,cost:40}}[type];if(!cfg)return;if(cfg.cost&&f.power<cfg.cost)return;f.power-=cfg.cost||0;f.attack={type,...cfg,t:0,hit:false,spawned:false};f.state='attack';f.row=cfg.row;f.frame=0;f.clock=0;if(type==='charge')f.vx=f.dir*390;window.arcadeAudio.effect(type==='neon'||type==='pulse'?'start':'confirm');}
  playerInput(dt){const f=this.player;if(f.hitstun||f.attack||this.countdown>0||this.endTimer)return;let move=0;if(this.keys.has('arrowleft'))move--;if(this.keys.has('arrowright'))move++;f.vx=move*245;if(move){f.state='walk';f.row=1}else{f.state='idle';f.row=0}if(this.pressed.has('arrowup')&&f.ground){f.vy=-650;f.ground=false;f.state='jump';f.row=3;}if(this.pressed.has('shift'))f.vx=f.dir*460;if(this.pressed.has('j'))this.attack(f,'jab');if(this.pressed.has('k'))this.attack(f,'kick');if(this.pressed.has('u'))this.attack(f,'heavy');if(this.pressed.has('i'))this.attack(f,'sweep');if(this.pressed.has('l'))this.attack(f,'neon');if(this.pressed.has('o'))this.attack(f,'spin');}
  cpuThink(dt){const f=this.cpu,p=this.player;if(f.hitstun||f.attack||this.countdown>0||this.endTimer)return;f.ai-=dt;if(f.ai>0)return;f.ai=.22+Math.random()*.25;const dist=Math.abs(p.x-f.x);if(dist>245){f.vx=f.dir*185;f.state='walk';f.row=1;if(Math.random()<.18)this.attack(f,'charge');}else if(dist<115){f.vx=-f.dir*80;if(Math.random()<.42&&f.power>=40)this.attack(f,'pulse');else this.attack(f,'charge');}else{f.vx=0;f.state='idle';f.row=0;if(Math.random()<.45)this.attack(f,f.power>=40&&Math.random()<.5?'pulse':'charge');}}
  updateFighter(f,dt){if(f.hitstun>0){f.hitstun-=dt;f.vx*=.88;f.state='hit';f.row=1;}if(f.attack){f.attack.t+=dt;const a=f.attack;f.frame=Math.min(5,Math.floor(a.t/a.duration*6));if(a.type==='charge')f.vx=f.dir*390;if(a.projectile&&!a.spawned&&a.t>=a.active[0]){a.spawned=true;this.projectiles.push({owner:f,x:f.x+f.dir*90,y:f.y-145,vx:f.dir*430,life:1.8,damage:a.damage});}if(!a.projectile&&!a.hit&&a.t>=a.active[0]&&a.t<=a.active[1])this.tryHit(f,f.side==='p'?this.cpu:this.player,a);if(a.t>=a.duration){f.attack=null;f.vx=0;f.state='idle';f.row=0;f.frame=0;}}else{f.clock+=dt;f.frame=Math.floor(f.clock*9)%6;}
    if(!f.ground){f.vy+=1800*dt;f.y+=f.vy*dt;if(f.y>=610){f.y=610;f.vy=0;f.ground=true;f.state='idle';f.row=0;}}f.x+=f.vx*dt;f.x=Math.max(120,Math.min(1160,f.x));if(!f.attack)f.vx*=.82;}
  tryHit(attacker,target,a){if(a.hit||target.life<=0)return;const dist=Math.abs(target.x-attacker.x);if(dist>a.reach)return;a.hit=true;const away=attacker.x>target.x?'arrowleft':'arrowright';const blocking=target.side==='p'&&this.keys.has(away)&&!target.attack&&target.ground;const damage=Math.round(a.damage*(blocking?.2:1));target.life=Math.max(0,target.life-damage);target.power=Math.min(100,target.power+(blocking?8:14));attacker.power=Math.min(100,attacker.power+10);target.hitstun=blocking?.06:.25;target.state=blocking?'guard':'hit';target.vx=attacker.dir*(blocking?55:220);if(blocking)this.callout('BLOCK!');window.arcadeAudio.effect(blocking?'move':'confirm');this.updateHud();}
  updateProjectiles(dt){for(const q of this.projectiles){q.x+=q.vx*dt;q.life-=dt;const target=q.owner.side==='p'?this.cpu:this.player;if(Math.abs(q.x-target.x)<65&&Math.abs(q.y-(target.y-120))<100&&q.life>0){q.life=0;this.tryHit(q.owner,target,{hit:false,reach:999,damage:q.damage});}}this.projectiles=this.projectiles.filter(q=>q.life>0&&q.x>0&&q.x<1280);}
  update(dt){if(this.countdown>0){this.countdown-=dt;this.pressed.clear();return}if(this.endTimer>0){this.endTimer-=dt;if(this.endTimer<=0)this.nextRound();this.pressed.clear();return}this.time=Math.max(0,this.time-dt);this.player.dir=this.cpu.x>=this.player.x?1:-1;this.cpu.dir=this.player.x>=this.cpu.x?1:-1;this.playerInput(dt);this.cpuThink(dt);this.updateFighter(this.player,dt);this.updateFighter(this.cpu,dt);const delta=this.cpu.x-this.player.x,gap=Math.abs(delta);if(gap<115){const sign=delta===0?1:Math.sign(delta),push=(115-gap)/2;this.player.x=Math.max(120,Math.min(1160,this.player.x-sign*push));this.cpu.x=Math.max(120,Math.min(1160,this.cpu.x+sign*push));}this.player.dir=this.cpu.x>=this.player.x?1:-1;this.cpu.dir=this.player.x>=this.cpu.x?1:-1;this.updateProjectiles(dt);if(this.player.life<=0||this.cpu.life<=0||this.time<=0)this.endRound();this.updateHud();this.pressed.clear();}
  endRound(){if(this.endTimer)return;const pWin=this.player.life>this.cpu.life;if(pWin)this.pWins++;else this.cWins++;this.endTimer=2.4;this.callout(pWin?'BIRROW WINS':'HALFRED WINS');this.updateHud();}
  nextRound(){if(this.pWins>=2||this.cWins>=2){this.callout(this.pWins>=2?'YOU WIN!':'GAME OVER');this.endTimer=999;return}this.round++;this.resetRound();}
  updateHud(){document.getElementById('p-life').style.transform=`scaleX(${this.player.life/1000})`;document.getElementById('c-life').style.transform=`scaleX(${this.cpu.life/1000})`;document.getElementById('p-power').style.width=this.player.power+'%';document.getElementById('c-power').style.width=this.cpu.power+'%';document.getElementById('timer').textContent=Math.ceil(this.time).toString().padStart(2,'0');document.getElementById('round-label').textContent='ROUND '+this.round;document.getElementById('p-rounds').textContent='● '.repeat(this.pWins)+'○ '.repeat(2-this.pWins);document.getElementById('c-rounds').textContent='● '.repeat(this.cWins)+'○ '.repeat(2-this.cWins);}
  processedFrame(key,img,row,col){const cacheKey=key+row+'-'+col;if(this.frameCache.has(cacheKey))return this.frameCache.get(cacheKey);const c=document.createElement('canvas');c.width=256;c.height=256;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,col*256,row*256,256,256,0,0,256,256);if(location.protocol==='file:'||key==='cpu'||key==='pm'||key==='pa'){this.frameCache.set(cacheKey,c);return c;}const data=x.getImageData(0,0,256,256),d=data.data;if(d[3]===0&&d[1023]===0&&d[261123]===0&&d[262143]===0){this.frameCache.set(cacheKey,c);return c;}const seen=new Uint8Array(65536),queue=[0,255,65280,65535];let head=0;while(head<queue.length){const p=queue[head++];if(seen[p])continue;seen[p]=1;const px=p%256,py=(p/256)|0,ii=p*4,neighbors=[p-1,p+1,p-256,p+256];d[ii+3]=0;for(const n of neighbors){if(n<0||n>=65536||seen[n])continue;const nx=n%256,ny=(n/256)|0;if(Math.abs(nx-px)+Math.abs(ny-py)!==1)continue;const j=n*4,dr=d[ii]-d[j],dg=d[ii+1]-d[j+1],db=d[ii+2]-d[j+2];if(dr*dr+dg*dg+db*db<620)queue.push(n);}}x.putImageData(data,0,0);this.frameCache.set(cacheKey,c);return c;}
  drawFighter(f){let img,key,row=f.row,col=f.frame;if(f.side==='p'){if(f.state==='attack'){img=this.assets.pAttack;key='pa'}else if(f.state==='hit'){img=this.assets.pReact;key='pr'}else{img=this.assets.pMove;key='pm'}}else{img=this.assets.cpu;key='cpu'}if(!img)return;const frame=this.processedFrame(key,img,row,col);const scale=f.side==='p'?1.28:1.34,w=256*scale,h=256*scale,nativeDir=f.side==='p'?1:-1,flip=f.dir!==nativeDir;this.ctx.save();if(flip){this.ctx.translate(f.x,0);this.ctx.scale(-1,1);this.ctx.drawImage(frame,-w/2,f.y-h,w,h)}else this.ctx.drawImage(frame,f.x-w/2,f.y-h,w,h);this.ctx.restore();}
  draw(){const c=this.ctx;c.clearRect(0,0,1280,720);if(this.assets.bg)c.drawImage(this.assets.bg,0,0,1280,720);c.fillStyle='rgba(3,4,20,.1)';c.fillRect(0,0,1280,720);for(const q of this.projectiles){const g=c.createRadialGradient(q.x,q.y,4,q.x,q.y,55);g.addColorStop(0,'#fff');g.addColorStop(.25,'#4ffaff');g.addColorStop(.65,'#f63eff');g.addColorStop(1,'transparent');c.fillStyle=g;c.beginPath();c.arc(q.x,q.y,55,0,Math.PI*2);c.fill();}this.drawFighter(this.player);this.drawFighter(this.cpu);}
  loop(t){if(!this.running)return;const dt=Math.min(.033,(t-this.last)/1000||0);this.last=t;this.update(dt);this.draw();requestAnimationFrame(n=>this.loop(n));}
  status(){return{running:this.running,round:this.round,time:Math.ceil(this.time),playerLife:this.player?.life,cpuLife:this.cpu?.life,playerPower:this.player?.power,cpuPower:this.cpu?.power,playerWins:this.pWins,cpuWins:this.cWins};}
}
window.fightEngine=new StreetFight();
